        self._service._stock.set(sku, new_on_hand)

        return Response(200, {"sku": sku, "on_hand": new_on_hand})

    def handle_fulfilment_summary(self) -> Response:
        orders = self._service._orders.list_all()

        open_orders = sum(1 for order in orders if order.status != "cancelled")
        units_to_pick = sum(item.quantity for order in orders if order.status != "cancelled"
                            for item in order.items)

        stock_levels = self._service._stock.all_levels()
        low_stock_products = sum(1 for sku, on_hand in stock_levels.items()
                                 if on_hand < 5 and self._service._catalog.get(sku)
                                 and self._service._catalog.get(sku).active)

        return Response(200, {
            "open_orders": open_orders,
            "units_to_pick": units_to_pick,
            "low_stock_products": low_stock_products,
        })
